import type { Category, Product } from "@/types";
import productsJson from "./products.lite.json";
import categoriesJson from "./categories.json";

/**
 * Client-safe seed catalog. This is the *lite* catalog (generated by
 * scripts/build-lite-catalog.mjs): reviews, full descriptions, spec text and
 * extra gallery images are omitted to keep the browser bundle small. Product
 * pages receive those from `@/data/server` via props.
 */
export const SEED_PRODUCTS = productsJson as Product[];
export const SEED_CATEGORIES = categoriesJson as Category[];
